/**
 * The subset of `userIds` who are suspended in `orgId`. Used by the paths that
 * must leave a suspended member out: notifications and the digest.
 */
export async function listSuspendedUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "suspended"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

