/**
 * Suspension: a suspended member keeps their membership, role and seat, but
 * cannot act, receive notifications or digests, be handed new work, or be
 * mentioned. Reinstating reverses all of it.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit, subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as commentService from "@/server/services/comment-service";
import * as digestService from "@/server/services/digest-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { MemberSuspendedError } from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, IssueId, MemberId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Role } from "@/types/member";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

/** Records every payload of one event type until `off()` is called. */
function capture<K extends TaskflowEventType>(type: K) {
  const payloads: TaskflowEventMap[K][] = [];
  const off: Unsubscribe = subscribe(type, (payload) => {
    payloads.push(payload);
  });
  return { payloads, off };
}

async function memberIdOf(tenant: Tenant, role: Role): Promise<MemberId> {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`fixture ${role} missing`);
  return member.id;
}

describe("suspending and reinstating a member", () => {
  it("keeps the membership, role and seat, and publishes member.suspended", async () => {
    const tenant = await createTenant("suspend-basic");
    const memberId = await memberIdOf(tenant, "viewer");
    const seen = capture("member.suspended");

    const suspended = await memberService.suspendMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId,
    });
    seen.off();

    expect(suspended).toMatchObject({ id: memberId, role: "viewer", status: "suspended" });
    expect(seen.payloads).toEqual([
      expect.objectContaining({
        memberId,
        userId: tenant.userIds.viewer,
        actorId: tenant.userIds.admin,
      }),
    ]);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
  });

  it("reinstates a suspended member and publishes member.reinstated", async () => {
    const tenant = await createTenant("reinstate-basic");
    const memberId = await memberIdOf(tenant, "member");
    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    const seen = capture("member.reinstated");

    const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    seen.off();

    expect(reinstated.status).toBe("active");
    expect(seen.payloads).toHaveLength(1);
  });

  it("returns a member already in the requested state unchanged and publishes nothing", async () => {
    const tenant = await createTenant("suspend-noop");
    const memberId = await memberIdOf(tenant, "member");
    const viewerId = await memberIdOf(tenant, "viewer");
    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    const suspendedSeen = capture("member.suspended");
    const reinstatedSeen = capture("member.reinstated");

    const again = await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    const alreadyActive = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewerId,
    });
    suspendedSeen.off();
    reinstatedSeen.off();

    expect(again.status).toBe("suspended");
    expect(alreadyActive.status).toBe("active");
    expect(suspendedSeen.payloads).toHaveLength(0);
    expect(reinstatedSeen.payloads).toHaveLength(0);
  });

  it("refuses to suspend yourself, and an admin suspending an owner, changing nothing", async () => {
    const tenant = await createTenant("suspend-refusals");
    const ownerId = await memberIdOf(tenant, "owner");
    const seen = capture("member.suspended");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerId,
      }),
    ).rejects.toThrow(/yourself/);
    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: ownerId,
      }),
    ).rejects.toThrow(/cannot suspend or reinstate/);
    seen.off();

    expect(seen.payloads).toHaveLength(0);
    const owner = await memberRepo.findMemberById(tenant.org.id, ownerId);
    expect(owner?.status).toBe("active");
  });

  it("treats a removed member as not found, for suspend and reinstate alike", async () => {
    const tenant = await createTenant("suspend-removed");
    const memberId = await memberIdOf(tenant, "viewer");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("does not count a suspended owner as one of the owners that must remain", async () => {
    const tenant = await createTenant("suspend-last-owner");
    const ownerId = await memberIdOf(tenant, "owner");
    const adminId = await memberIdOf(tenant, "admin");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminId,
      role: "owner",
    });
    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminId,
    });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerId,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);
  });
});

describe("a suspended member while suspended", () => {
  it("gets no actor and drops the workspace from their organization list", async () => {
    const tenant = await createTenant("suspend-access");
    const viewerId = tenant.userIds.viewer;
    const memberId = await memberIdOf(tenant, "viewer");

    const before = await organizationService.listOrganizationsForUser(viewerId);
    expect(before.map((org) => org.id)).toContain(tenant.org.id);

    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });

    await expect(memberService.resolveActor(viewerId, tenant.org.id)).resolves.toBeNull();
    await expect(
      sessionService.resolveActorForOrg(
        {
          userId: viewerId,
          email: "viewer@suspend-access.test",
          activeOrgId: null,
          expiresAt: toIsoTimestamp(new Date(Date.now() + 86_400_000)),
        },
        tenant.org.slug,
      ),
    ).resolves.toBeNull();

    const after = await organizationService.listOrganizationsForUser(viewerId);
    expect(after.map((org) => org.id)).not.toContain(tenant.org.id);
  });

  it("keeps the seat in the summary count and the usage recount", async () => {
    const tenant = await createTenant("suspend-seats");
    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "viewer"),
    });

    const summary = await organizationService.getOrganizationSummary(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(summary.memberCount).toBe(4);

    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.seatsUsed).toBe(4);
  });

  it("receives no notification from notify() or from the event fan-out", async () => {
    const tenant = await createTenant("suspend-notify");
    const viewerId = tenant.userIds.viewer;
    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "viewer"),
    });

    const direct = await notificationService.notify(
      tenant.org.id,
      "issue_assigned",
      [viewerId],
      {
        title: "Assigned",
        body: "Issue is yours",
        href: "/issues/x",
        actorId: tenant.userIds.owner,
      },
    );
    expect(direct).toEqual([]);

    await emit("issue.assigned", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: toIsoTimestamp(new Date()),
      issueId: "iss-suspended" as IssueId,
      projectId: tenant.project.id,
      previousAssigneeId: null,
      assigneeId: viewerId,
    });

    const page = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: viewerId,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(page.total).toBe(0);
  });

  it("is skipped by the digest, and digests earlier unread notifications after reinstatement", async () => {
    const tenant = await createTenant("suspend-digest");
    const viewerId = tenant.userIds.viewer;
    const memberId = await memberIdOf(tenant, "viewer");
    await notificationService.notify(tenant.org.id, "issue_assigned", [viewerId], {
      title: "Before suspension",
      body: "Assigned earlier",
      href: "/issues/a",
      actorId: tenant.userIds.owner,
    });

    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    const windowStart = "2000-01-01T00:00:00.000Z" as IsoTimestamp;
    const windowEnd = toIsoTimestamp(new Date(Date.now() + 60_000));

    await expect(
      digestService.buildDigest(tenant.org.id, viewerId, windowStart, windowEnd),
    ).resolves.toBeNull();

    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    const bundle = await digestService.buildDigest(
      tenant.org.id,
      viewerId,
      windowStart,
      windowEnd,
    );
    expect(bundle?.entries.map((entry) => entry.title)).toEqual(["Before suspension"]);
  });

  it("cannot be handed new work, but keeps the issues already assigned to them", async () => {
    const tenant = await createTenant("suspend-work");
    const viewerId = tenant.userIds.viewer;
    const memberId = await memberIdOf(tenant, "viewer");
    const alreadyTheirs = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already theirs",
        assigneeId: viewerId,
      }),
    );
    const notYetTheirs = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Not yet theirs" }),
    );

    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId,
    });
    const created = capture("issue.created");
    const assignedSeen = capture("issue.assigned");
    const issuesBefore = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    await expect(
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Refused",
          assigneeId: viewerId,
        }),
      ),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    await expect(
      issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: notYetTheirs.id,
        assigneeId: viewerId,
      }),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    created.off();
    assignedSeen.off();

    expect(created.payloads).toHaveLength(0);
    expect(assignedSeen.payloads).toHaveLength(0);
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id),
    ).resolves.toBe(issuesBefore);
    await expect(
      issueRepo.findIssueById(tenant.org.id, notYetTheirs.id),
    ).resolves.toMatchObject({ assigneeId: null });
    await expect(
      issueRepo.findIssueById(tenant.org.id, alreadyTheirs.id),
    ).resolves.toMatchObject({ assigneeId: viewerId });

    const unassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: alreadyTheirs.id,
      assigneeId: null,
    });
    expect(unassigned.assigneeId).toBeNull();
  });

  it("cannot be mentioned, by handle or by a client-supplied id", async () => {
    const tenant = await createTenant("suspend-mention");
    const viewerId = tenant.userIds.viewer;
    const adminId = tenant.userIds.admin;
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention target" }),
    );
    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "viewer"),
    });
    const seen = capture("comment.created");

    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Ping @viewer and @admin",
      parentId: null,
      mentionedUserIds: [viewerId],
    });
    seen.off();

    expect(comment.mentionedUserIds).toEqual([adminId]);
    expect(seen.payloads).toEqual([
      expect.objectContaining({ mentionedUserIds: [adminId] }),
    ]);
    const mentions = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: viewerId,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    expect(mentions.total).toBe(0);
  });
});

