/**
 * Locks a member out without removing them: the membership, role and seat all
 * stay. Suspending an already-suspended member returns it unchanged.
 */
export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await loadMemberForStatusChange(actor, input);
  if (member.status !== "active") return member;

  if (member.role === "owner") {
    await assertAnotherActiveOwner(input.orgId, input.memberId);
  }

  const suspended = await memberRepo.updateMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Lifts a suspension. Reinstating a member who is not suspended returns them unchanged. */
export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await loadMemberForStatusChange(actor, input);
  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.updateMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/**
 * The guards suspend and reinstate share: tenant scope, a member that has not
 * been removed, `member:remove`, then the two rules `can()` cannot express —
 * nobody acts on themselves, and nobody acts on a role above their own.
 */
async function loadMemberForStatusChange(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findLiveMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
